{
  "qid": "0021_acura_l2_01",
  "sample_id": "0021",
  "gen_prompt": "为“讴歌”创作一张写实商业广告图：一辆深蓝色豪华轿车停在现代美术馆入口前湿润的石板地面上，车头正对镜头，采用略低机位的中近景，前脸中央区域完整清晰、无遮挡。画面左后方有一名穿米色风衣的女性侧身走过，不接触车辆；右后方是一排暖白色立柱灯。傍晚蓝调时刻，地面呈现柔和倒影，16:9横幅，摄影写实风格，不出现任何广告文案。",
  "invocation": "L2",
  "knowledge_dim": "汽车品牌视觉识别与车标几何结构知识",
  "fidelity_checks": [
    {
      "check": "车头前脸中央须出现讴歌品牌的图形徽标，不能只出现“讴歌”或“ACURA”等文字而没有图形标识。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "1"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "前脸中央完全没有图形徽标，或只用“讴歌”“ACURA”等文字充当唯一品牌标识。",
        "tier_1": "前脸中央清楚出现可辨认的讴歌图形徽标，不依赖文字即可确认存在图形品牌标识。",
        "tier_2": "在满足 Pass 的基础上，图形徽标安装位置、轮廓边界和内部结构均高度清晰，缩放查看仍可稳定辨认。"
      },
      "variants_used": "",
      "visibility_requirement": "题面已锁定车头正对镜头且前脸中央完整清晰、无遮挡；若该区域因生成结果裁切、模糊或遮挡而无法核验，按缺失处理并记 0。"
    },
    {
      "check": "徽标主体须呈卡钳式的大写“A”字形整体轮廓，而不是普通印刷体“A”、单纯字母文字或其他几何符号。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "徽标被画成普通印刷体大写“A”、普通三角符号、其他字母或缺乏卡钳结构的任意图案。",
        "tier_1": "徽标整体明确呈现卡钳式“A”字轮廓，能够与普通印刷体字母区分。",
        "tier_2": "在满足 Pass 的基础上，卡钳式几何语言精确鲜明，两侧笔画的收束、张开和机械测量工具般的造型均得到细致表现。"
      },
      "variants_used": "",
      "visibility_requirement": "须能看清徽标的整体外轮廓；题面已保证正面无遮挡，若轮廓模糊到无法区分卡钳式造型与普通字母，记 0。"
    },
    {
      "check": "构成徽标的两条斜笔画须在顶部交汇，并分别向左下方和右下方张开。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "两条斜笔画顶部不交汇、彼此平行、朝同一侧倾斜，或下端没有向左右两侧张开。",
        "tier_1": "两条斜笔画在顶部正确交汇，下部清楚地向左下和右下分开。",
        "tier_2": "在满足 Pass 的基础上，顶部交汇点锐利准确，左右张开方向和几何平衡均表现得清楚且精密。"
      },
      "variants_used": "",
      "visibility_requirement": "徽标顶部及左右两侧须同时可见；若生成图裁掉顶部或任一侧，导致无法确认交汇与张开方向，记 0。"
    },
    {
      "check": "徽标两条斜腿之间须有一根水平横杠，将左右两腿连接起来。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "水平横杠缺失、断裂而未连接两腿、明显倾斜成斜杠，或被画成多根杂乱线条。",
        "tier_1": "两条斜腿之间存在一根清晰的水平横杠，并确实连接左右两腿。",
        "tier_2": "在满足 Pass 的基础上，横杠位置、水平度、连接端点和线条粗细均处理精确，与两腿形成干净统一的结构。"
      },
      "variants_used": "",
      "visibility_requirement": "须能分辨徽标内部的横向连接结构；若该区域被高光、阴影或模糊完全吞没，无法确认横杠存在，记 0。"
    },
    {
      "check": "徽标横杠上方、两条斜腿之间的三角形区域须保持镂空，不得填成实心封闭块面。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "横杠上方的内部区域被填成实心三角形、封闭色块，或因错误结构完全没有可见镂空。",
        "tier_1": "横杠上方两腿之间存在明确可见的镂空区域，没有被实心图形填满。",
        "tier_2": "在满足 Pass 的基础上，上部镂空边界锐利、比例清楚，并与外部笔画形成精确而干净的负形空间。"
      },
      "variants_used": "",
      "visibility_requirement": "徽标内部上半部须清晰可见；若因反光或低分辨率无法判断该区域是镂空还是实心，记 0。"
    },
    {
      "check": "徽标横杠下方、两条斜腿之间的区域须保持开放镂空，不得封成实心三角形或块状底座。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "横杠下方被填成实心块、封闭三角形或连续底板，导致两腿之间没有开放空间。",
        "tier_1": "横杠下方两条斜腿之间保持清楚的开放镂空，左右斜腿彼此可区分。",
        "tier_2": "在满足 Pass 的基础上，下部开口轮廓完整、左右间距和负形关系精确，未被安装底座或装饰错误侵占。"
      },
      "variants_used": "",
      "visibility_requirement": "徽标内部下半部及两条斜腿须可见；若车牌、装饰件或生成伪影遮住该区域而无法核验，记 0。"
    },
    {
      "check": "画面中的品牌识别不得由本田“H”字、雷克萨斯、英菲尼迪或其他汽车品牌的车标或品牌名替代。",
      "lens": "K3",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "前脸出现本田“H”字或雷克萨斯、英菲尼迪等其他品牌标识，或者其他品牌名成为车辆的主要品牌识别。",
        "tier_1": "车辆品牌识别为讴歌，没有其他汽车品牌标识取代或混淆主体身份。",
        "tier_2": "在满足 Pass 的基础上，所有可见品牌识别细节均统一指向讴歌，完全没有混标、拼接或近似其他品牌的歧义。"
      },
      "variants_used": "",
      "visibility_requirement": "核验车头及画面内所有清晰可见的品牌识别区域；远处小到无法辨读的环境标记不参与判断。若主体车头标识不可辨认，记 0。"
    },
    {
      "check": "讴歌徽标内部及周围不得附加狮子、鹰、奔马等动物形象，主体应保持抽象几何构成。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "徽标被画成动物图案，或在其内部、顶部、两侧附加狮子、鹰、奔马等可辨动物部件。",
        "tier_1": "徽标没有任何动物形象，仅以抽象几何笔画构成主体。",
        "tier_2": "在满足 Pass 的基础上，徽标几何边界纯净克制，与附近格栅装饰清晰分离，不产生任何动物轮廓误读。"
      },
      "variants_used": "",
      "visibility_requirement": "徽标及紧邻装饰区域须可见；只判断是否有动物图案被整合进品牌标识，不把背景中的自然动物误算为附加部分。主体徽标不可见时记 0。"
    },
    {
      "check": "讴歌徽标不得融入人物、头像或人体部件等具象图案，主体应只由抽象几何笔画组成。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "徽标内部或轮廓上出现人物、脸孔、人体剪影或人体部件，导致标识成为具象人物图案。",
        "tier_1": "徽标本身不含人物或人体元素，仅呈抽象几何结构。",
        "tier_2": "在满足 Pass 的基础上，抽象结构表达高度纯粹，所有笔画归属明确，不与画面中的人物或反射叠合成具象人形。"
      },
      "variants_used": "",
      "visibility_requirement": "只核验徽标自身及与其直接连接的装饰；题面中的路人可以存在，但不得被整合为徽标构成。若徽标不可见或无法与人物反射区分，记 0。"
    },
    {
      "check": "画面的概念主体须明确表现为汽车品牌及其车辆，不得将“讴歌”的中文字面义误作歌手演唱、歌舞表演或颂扬庆典，并以此取代汽车品牌呈现。",
      "lens": "K1",
      "anchor": {
        "type": "direct",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": ""
      },
      "rubric": {
        "tier_0": "主体被画成歌手演唱、舞台歌舞或颂扬庆典，车辆与汽车品牌识别缺失；或此类字面义场景完全取代讴歌汽车品牌主题。",
        "tier_1": "画面主体明确是一辆讴歌汽车及其品牌广告场景，没有把概念误解为歌唱或颂扬活动。",
        "tier_2": "在满足 Pass 的基础上，车辆、商业展示语境与正确品牌识别形成完整统一的汽车品牌叙事，概念归类毫无歧义。"
      },
      "variants_used": "",
      "visibility_requirement": "按整幅画面的主导主体与场景类型判断；题面中的路人不构成歌唱场景。若汽车缺失或被演出活动边缘化到无法成为主体，记 0。"
    }
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
